files.content:
[hidden] { display: none !important; }

:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #f0f0f5;
  --accent: #ffcc00;
  --accent-hover: #ffdb4d;
  --border: #3e3e5e;
  --star-empty: #555577;
  --star-filled: #ffcc00;
  --danger: #ff6b6b;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  --radius: 8px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border: 2px solid var(--border);
  border-radius: var(--radius);
  padding: 24px;
  width: 100%;
  max-width: 600px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.4);
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 16px;
  text-align: center;
  color: var(--accent);
  letter-spacing: 1px;
}

h2 {
  font-size: 1.25rem;
  margin-bottom: 12px;
  color: var(--accent);
}

.review-form {
  margin-bottom: 24px;
}

.label {
  display: block;
  margin-bottom: 6px;
  font-weight: 600;
  font-size: 1rem;
}

.rating-input {
  margin-bottom: 16px;
}

.stars {
  display: flex;
  gap: 4px;
  margin: 6px 0;
}

.star {
  background: none;
  border: none;
  font-size: 2rem;
  cursor: pointer;
  color: var(--star-empty);
  padding: 0 2px;
  transition: color 0.15s, transform 0.1s;
  line-height: 1;
  border-radius: 4px;
}

.star:hover,
.star.hovered {
  color: var(--star-filled);
}

.star:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.star.selected {
  color: var(--star-filled);
}

.star:active {
  transform: scale(0.9);
}

.selected-rating {
  display: block;
  font-size: 0.9rem;
  color: #aaaacc;
  margin-top: 4px;
}

textarea {
  width: 100%;
  padding: 10px;
  border: 2px solid var(--border);
  border-radius: var(--radius);
  background: #1e1e2f;
  color: var(--text);
  font-family: var(--font);
  font-size: 1rem;
  resize: vertical;
  margin-bottom: 12px;
  transition: border-color 0.15s;
}

textarea:focus {
  outline: none;
  border-color: var(--accent);
}

.btn {
  background: var(--accent);
  color: #1e1e2f;
  border: none;
  padding: 12px 24px;
  font-size: 1rem;
  font-weight: 700;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  width: 100%;
}

.btn:hover {
  background: var(--accent-hover);
}

.btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.98);
}

.average-rating {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 8px;
  margin-bottom: 16px;
  padding: 12px;
  background: #1e1e2f;
  border-radius: var(--radius);
  border: 1px solid var(--border);
}

.avg-label {
  font-weight: 600;
}

#avg-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent);
}

.avg-stars {
  color: var(--star-filled);
  font-size: 1.2rem;
  letter-spacing: 2px;
}

.review-count {
  font-size: 0.9rem;
  color: #aaaacc;
  margin-left: auto;
}

.review-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
  max-height: 300px;
  overflow-y: auto;
  padding-right: 4px;
}

.review-item {
  background: #1e1e2f;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 12px;
}

.review-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 6px;
}

.review-stars {
  color: var(--star-filled);
  font-size: 1.1rem;
  letter-spacing: 1px;
}

.review-comment {
  font-size: 0.95rem;
  color: #d0d0e0;
  word-break: break-word;
}

@media (max-width: 400px) {
  .card { padding: 16px; }
  h1 { font-size: 1.4rem; }
  .star { font-size: 1.6rem; }
  .btn { padding: 10px 16px; }
  .review-header { flex-direction: column; align-items: flex-start; gap: 4px; }
}

(function() {
  'use strict';

  const starContainer = document.getElementById('star-container');
  const stars = Array.from(starContainer.querySelectorAll('.star'));
  const selectedRatingEl = document.getElementById('selected-rating');
  const commentEl = document.getElementById('comment');
  const submitBtn = document.getElementById('submit-btn');
  const reviewList = document.getElementById('review-list');
  const avgValueEl = document.getElementById('avg-value');
  const avgStarsEl = document.getElementById('avg-stars');
  const reviewCountEl = document.getElementById('review-count');

  let currentRating = 0;
  let reviews = [];

  function updateStarsDisplay(rating) {
    stars.forEach((star, index) => {
      star.classList.toggle('selected', index < rating);
    });
    selectedRatingEl.textContent = rating + ' star' + (rating !== 1 ? 's' : '') + ' selected';
  }

  function clearHover() {
    stars.forEach(star => star.classList.remove('hovered'));
  }

  function highlightStars(rating) {
    stars.forEach((star, index) => {
      star.classList.toggle('hovered', index < rating);
    });
  }

  stars.forEach((star, index) => {
    const value = index + 1;

    star.addEventListener('mouseenter', () => {
      highlightStars(value);
    });

    star.addEventListener('mouseleave', () => {
      clearHover();
    });

    star.addEventListener('click', () => {
      currentRating = value;
      updateStarsDisplay(currentRating);
    });

    star.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        currentRating = value;
        updateStarsDisplay(currentRating);
      } else if (e.key === 'ArrowRight' || e.key === 'ArrowUp') {
        e.preventDefault();
        const next = Math.min(5, value + 1);
        stars[next - 1].focus();
        currentRating = next;
        updateStarsDisplay(currentRating);
      } else if (e.key === 'ArrowLeft' || e.key === 'ArrowDown') {
        e.preventDefault();
        const prev = Math.max(1, value - 1);
        stars[prev - 1].focus();
        currentRating = prev;
        updateStarsDisplay(currentRating);
      }
    });
  });

  starContainer.addEventListener('mouseleave', clearHover);

  function updateAverage() {
    if (reviews.length === 0) {
      avgValueEl.textContent = '0.0';
      avgStarsEl.textContent = '';
      reviewCountEl.textContent = '(0 reviews)';
      return;
    }
    const sum = reviews.reduce((acc, r) => acc + r.rating, 0);
    const avg = sum / reviews.length;
    avgValueEl.textContent = avg.toFixed(1);
    const fullStars = Math.round(avg);
    avgStarsEl.textContent = '★'.repeat(fullStars) + '☆'.repeat(5 - fullStars);
    reviewCountEl.textContent = '(' + reviews.length + ' review' + (reviews.length !== 1 ? 's' : '') + ')';
  }

  function renderReviews() {
    reviewList.innerHTML = '';
    reviews.forEach(review => {
      const li = document.createElement('li');
      li.className = 'review-item';
      const header = document.createElement('div');
      header.className = 'review-header';
      const starsSpan = document.createElement('span');
      starsSpan.className = 'review-stars';
      starsSpan.textContent = '★'.repeat(review.rating) + '☆'.repeat(5 - review.rating);
      starsSpan.setAttribute('aria-label', review.rating + ' out of 5 stars');
      header.appendChild(starsSpan);
      const commentP = document.createElement('p');
      commentP.className = 'review-comment';
      commentP.textContent = review.comment;
      li.appendChild(header);
      li.appendChild(commentP);
      reviewList.appendChild(li);
    });
  }

  submitBtn.addEventListener('click', () => {
    const comment = commentEl.value.trim();
    if (currentRating === 0) {
      alert('Please select a star rating.');
      return;
    }
    if (!comment) {
      alert('Please enter a comment.');
      return;
    }
    reviews.push({ rating: currentRating, comment: comment });
    renderReviews();
    updateAverage();
    currentRating = 0;
    updateStarsDisplay(0);
    commentEl.value = '';
    stars[0].focus();
  });

  updateStarsDisplay(0);
  updateAverage();
})();
